"""Chebyshev polynomial of the first kind, elementwise: T_n(x).

Semantics reproduced from the target's own aten::special_chebyshev_polynomial_t
(verified on device):

  * the degree is truncated toward zero to an integer before evaluation,
  * x > 1   -> cosh(n * acosh(x))
  * x < -1  -> (-1)**n * cosh(n * acosh(-x))
  * else    -> cos(n * acos(x))

The Gems contract for this operator accepts float32/float64 compute (integral
degrees are cast in-kernel); every other dtype raises ValueError.  A Python
number degree behaves like a wrapped scalar and never changes the dtype.
"""

import logging

import torch
import triton
import triton.language as tl
from triton.language.extra import libdevice as _ld

_F32 = torch.float32
_F64 = torch.float64
_BLOCK = 1024
_NUM_WARPS = 4

# The Gems dispatch tests capture this record with
# caplog.at_level("DEBUG", logger="flag_gems.ops.special_chebyshev_polynomial_t"),
# so the message must be emitted as DEBUG on exactly that logger, like the
# reference flag_gems operators do.  The timing path leaves that logger at
# WARNING, so nothing is emitted and no formatting cost is paid.
_DEBUG = logging.DEBUG
_log = logging.getLogger("flag_gems.ops.special_chebyshev_polynomial_t")
_LOG_MSG = "GEMS_ILUVATAR SPECIAL_CHEBYSHEV_POLYNOMIAL_T"

_INT_DTYPES = frozenset(
    (torch.bool, torch.int8, torch.uint8, torch.int16, torch.int32, torch.int64)
)


@triton.jit
def _cheb_rec(x, deg):
    """T_deg(x) for an integer degree, by the forward recurrence in pure FMA.

    T_0 = 1, T_1 = x, T_k = 2x*T_{k-1} - T_{k-2}.  Because the degree is
    truncated to an integer this is exactly the same polynomial on every branch
    the reference splits on, so it needs no domain gate, no acosh/cosh, no sign
    term and no transcendental call for any real x.
    """
    t0 = tl.zeros_like(x) + 1.0
    t1 = x
    for _ in range(2, deg + 1):
        t2 = 2.0 * x * t1 - t0
        t0 = t1
        t1 = t2
    return tl.where(deg == 0, t0, t1)


@triton.jit
def _cheb_trans(x, n_int, IS_F64: tl.constexpr):
    """Reference-shaped cos/cosh form, used for per-element (tensor) degrees.

    The block-uniform register test keeps the whole out-of-domain sequence
    (acosh + cosh + sign) off the fast path whenever every lane of the block is
    inside [-1, 1], which mirrors the reference kernel's per-element branches
    while staying a real uniform branch.  The predicate is inclusive and tested
    on the unclamped x, so x == +-1 stays on the cosine branch and NaN falls
    through to the general expression.
    """
    if IS_F64:
        n = n_int.to(tl.float64)
    else:
        n = n_int.to(tl.float32)
    if tl.max(tl.abs(x)) <= 1.0:
        # In-domain the result is bounded by 1 in magnitude and the collected
        # accuracy contract allows atol 1e-4, so the hardware cosine (argument
        # error ~|n*acos(x)|*eps + 2^-21 <= ~4e-6 here) is used instead of the
        # full-precision libdevice polynomial.
        if IS_F64:
            t = _ld.cos(n * _ld.acos(x))
        else:
            t = _ld.fast_cosf(n * _ld.acos(x))
    else:
        xc = tl.minimum(tl.maximum(x, -1.0), 1.0)
        ax = tl.maximum(tl.abs(x), 1.0)
        cv = _ld.cos(n * _ld.acos(xc))
        hv = _ld.cosh(n * _ld.acosh(ax))
        if IS_F64:
            sgn = (1 - 2 * (n_int & 1)).to(tl.float64)
        else:
            sgn = (1 - 2 * (n_int & 1)).to(tl.float32)
        t = tl.where(x > 1.0, hv, tl.where(x < -1.0, sgn * hv, cv))
    return t


@triton.jit
def _cheb_core(x_in, n_int, IS_F64: tl.constexpr, SCALAR_DEG: tl.constexpr):
    """Evaluate T_{n}(x) for an already truncated integer degree."""
    if IS_F64:
        x = x_in.to(tl.float64)
    else:
        x = x_in.to(tl.float32)
    if SCALAR_DEG:
        # Block-uniform degree: iterate the polynomial recurrence to it.  The
        # trip count is one scalar for the whole program, so no per-element
        # select chain is needed.
        t = _cheb_rec(x, tl.abs(n_int))
    else:
        t = _cheb_trans(x, n_int, IS_F64)
    return t


@triton.jit
def _cheb_linear(
    x_ptr,
    n_ptr,
    out_ptr,
    numel,
    n_scalar,
    N_MODE: tl.constexpr,
    IS_F64: tl.constexpr,
    SCALAR_DEG: tl.constexpr,
    EVEN: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        # numel is an exact multiple of BLOCK: no tail predicate, so the
        # contiguous blocked offsets let Triton emit wide vector accesses.
        xv = tl.load(x_ptr + offs)
        if N_MODE == 0:
            n_int = n_scalar
        elif N_MODE == 1:
            n_int = tl.load(n_ptr + offs).to(tl.int32)
        else:
            n_int = tl.load(n_ptr).to(tl.int32)
        t = _cheb_core(xv, n_int, IS_F64, SCALAR_DEG)
        tl.store(out_ptr + offs, t.to(out_ptr.dtype.element_ty))
    else:
        mask = offs < numel
        xv = tl.load(x_ptr + offs, mask=mask, other=0)
        if N_MODE == 0:
            n_int = n_scalar
        elif N_MODE == 1:
            n_int = tl.load(n_ptr + offs, mask=mask, other=0).to(tl.int32)
        else:
            n_int = tl.load(n_ptr).to(tl.int32)
        t = _cheb_core(xv, n_int, IS_F64, SCALAR_DEG)
        tl.store(out_ptr + offs, t.to(out_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _offsets(
    offs,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    s6,
    s7,
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    t6,
    t7,
    NDIM: tl.constexpr,
):
    sizes = (s0, s1, s2, s3, s4, s5, s6, s7)
    strides = (t0, t1, t2, t3, t4, t5, t6, t7)
    rem = offs
    off = tl.zeros_like(offs).to(tl.int64)
    for i in tl.static_range(NDIM):
        d = NDIM - 1 - i
        sz = sizes[d]
        idx = rem % sz
        rem = rem // sz
        off += idx.to(tl.int64) * strides[d].to(tl.int64)
    return off


